import type { DetailsHTMLAttributes, HTMLAttributes } from "react";

export function Accordion({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-w-full co-divide-y co-divide-black/15 ${className}`.trim()} {...props} />; }
export function AccordionItem({ className = "", ...props }: DetailsHTMLAttributes<HTMLDetailsElement>) { return <details className={`co-group co-py-1 ${className}`.trim()} {...props} />; }
export function AccordionTrigger({ className = "", children, ...props }: HTMLAttributes<HTMLElement>) { return <summary className={`co-flex co-cursor-pointer co-list-none co-items-center co-justify-between co-py-4 co-font-medium focus-visible:co-ring-2 ${className}`.trim()} {...props}>{children}<span aria-hidden="true" className="co-ms-2 co-inline-block co-transition group-open:co-rotate-180">↓</span></summary>; }
export function AccordionContent({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-pb-4 co-text-sm co-text-black/60 ${className}`.trim()} {...props} />; }
